/**
 * A generated file names how to regenerate it (ADR 0010, D13): every `src/**\/*.generated.ts` opens with
 * ``// GENERATED by `npm run <script>` from <path>. Do not edit.``, and `package.json` defines `<script>`, so a
 * reader who wants to change one finds its generator instead of editing it by hand. ESLint and the comment
 * rules skip these files; this rule is what still holds them. No allowlist: a generated file complies from
 * its first commit.
 */
import { readSource, filesUnder } from "../helpers/architecture/tree";

const HEADER = /^\/\/ GENERATED by `npm run ([\w:.-]+)` from (\S+)\. Do not edit\.$/;

/** `<file>: <problem>` when a generated file's first line is not the header, or names a script `scripts` lacks. */
export function generatedFileViolations(file: string, source: string, scripts: ReadonlySet<string>): string[] {
  if (!file.endsWith(".generated.ts")) return [];
  const first = source.split("\n", 1)[0] ?? "";
  const header = HEADER.exec(first);
  if (header === null) return [`${file}: no "// GENERATED by \`npm run <script>\` from <path>. Do not edit." first line`];
  const script = header[1] ?? "";
  return scripts.has(script) ? [] : [`${file}: npm script "${script}" is not in package.json`];
}

function packageScripts(): Set<string> {
  const pkg = JSON.parse(readSource("package.json")) as { scripts?: Record<string, string> };
  return new Set(Object.keys(pkg.scripts ?? {}));
}

describe("generated file rule applies as specified", () => {
  const scripts = new Set(["notices:types"]);

  it("passes a file whose first line names a defined script and its source", () => {
    // Arrange
    const source = "// GENERATED by `npm run notices:types` from contracts/consumed/skkuverse-crawler/notice.schema.json. Do not edit.\nexport interface A { a: number }\n";

    // Act & Assert
    expect(generatedFileViolations("src/x/x.document.generated.ts", source, scripts)).toEqual([]);
  });

  it("flags a missing or altered header", () => {
    // Arrange
    const sources = [
      "export interface A { a: number }\n",
      "/* GENERATED by `npm run notices:types` from a.json. Do not edit. */\n",
      "// GENERATED by npm run notices:types from a.json. Do not edit.\n",
      "// Generated by `npm run notices:types` from a.json.\n",
    ];

    // Act
    const violations = sources.map((s) => generatedFileViolations("src/x/x.document.generated.ts", s, scripts));

    // Assert
    expect(violations.map((v) => v.length)).toEqual([1, 1, 1, 1]);
  });

  it("flags a header that names a script package.json does not define", () => {
    // Arrange
    const source = "// GENERATED by `npm run no-such-script` from a.json. Do not edit.\n";

    // Act
    const violations = generatedFileViolations("src/x/x.document.generated.ts", source, scripts);

    // Assert
    expect(violations).toEqual(['src/x/x.document.generated.ts: npm script "no-such-script" is not in package.json']);
  });

  it("leaves a file that is not generated alone", () => {
    // Act & Assert
    expect(generatedFileViolations("src/x/x.document.ts", "export interface A { a: number }\n", scripts)).toEqual([]);
  });
});

describe("generated files", () => {
  it("open with the header that names their npm script", () => {
    // Arrange
    const scripts = packageScripts();

    // Act
    const violations = filesUnder("src").flatMap((f) => generatedFileViolations(f, readSource(f), scripts));

    // Assert
    expect(violations).toEqual([]);
  });
});
